using TaskFlow.API.Models; using TaskFlow.API.Data; using Microsoft.EntityFrameworkCore; namespace TaskFlow.API.Repositories; public class TeamAnalyticsSnapshotRepository : ITeamAnalyticsSnapshotRepository { private readonly AppDbContext _context; public TeamAnalyticsSnapshotRepository(AppDbContext context) { _context = context; } public async Task<TeamAnalyticsSnapshot?> GetLatestSnapshotAsync(int teamId) { return await _context.TeamAnalyticsSnapshots.Where(s => s.TeamId == teamId).OrderByDescending(s => s.CreatedAt).FirstOrDefaultAsync(); } public async Task AddSnapshotAsync(TeamAnalyticsSnapshot snapshot) { _context.TeamAnalyticsSnapshots.Add(snapshot); await _context.SaveChangesAsync(); } }
